function rebalanceAnswerPositions(topic) {
  const items = questionDatabase.filter((item) => item.topic === topic);
  items.forEach((item, index) => {
    const target = index % 4;
    const [correct] = item.options.splice(item.answer, 1);
    item.options.splice(target, 0, correct);
    item.answer = target;
  });
}
